effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat13;
bool u_xlatb13;
float u_xlat19;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + (-_offset.xy);
    u_xlat0 = texture(flow_map, u_xlat0.xy);
    u_xlat1.xy = u_xlat0.xy + vec2(-0.501960814, -0.501960814);
    u_xlat1.xy = u_xlat1.xy * vec2(_strength);
    u_xlatb13 = int(_blend)<0;
    if(u_xlatb13){
        u_xlat13.x = _cur_time * _speed + 0.5;
        u_xlat13.x = fract(u_xlat13.x);
        u_xlat13.xy = (-u_xlat1.xy) * u_xlat13.xx + acScreenNorm.xy;
        u_xlat2 = texture(inputImg, u_xlat13.xy);
    } else {
        u_xlat13.x = _cur_time * _speed;
        u_xlat13.x = fract(u_xlat13.x);
        u_xlat3.xy = (-u_xlat1.xy) * u_xlat13.xx + acScreenNorm.xy;
        u_xlat19 = _cur_time * _speed + 0.5;
        u_xlat19 = fract(u_xlat19);
        u_xlat1.xy = (-u_xlat1.xy) * vec2(u_xlat19) + acScreenNorm.xy;
        u_xlat13.x = (-u_xlat13.x) + 0.5;
        u_xlat13.x = u_xlat13.x + u_xlat13.x;
        u_xlat3 = texture(inputImg, u_xlat3.xy);
        u_xlat4 = texture(inputImg, u_xlat1.xy);
        u_xlat4 = (-u_xlat3) + u_xlat4;
        u_xlat2 = abs(u_xlat13.xxxx) * u_xlat4 + u_xlat3;
    }
    u_xlatb1 = 0<int(_show_canvas);
    u_xlat0 = u_xlat0 + vec4(-0.5, -0.5, -0.5, -0.5);
    u_xlat0 = u_xlat0 * vec4(0.5, 0.5, 0.5, 0.5) + u_xlat2;
    u_xlat0 = (bool(u_xlatb1)) ? u_xlat0 : u_xlat2;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
